  EXPECT_EQ(vk_relu(x, 4, out, 4), VK_OK);
  EXPECT_NEAR(out[0], 0.0f, 1e-6f);
  EXPECT_NEAR(out[1], 0.0f, 1e-6f);
  EXPECT_NEAR(out[2], 2.0f, 1e-6f);
