int32_t transform_token(int32_t raw_token, const int32_t* page_table_row,
                        const int32_t* topk_indices_offset, int32_t offset) {
  if (page_table_row != nullptr) return page_table_row[raw_token];
  if (topk_indices_offset != nullptr) return raw_token + offset;
  return raw_token;
}

}  // namespace

bool dsa_topk_transform_group_topk_supported(int32_t group_topk) {
  switch (group_topk) {
    case 128:
    case 160:
    case 192:
    case 224:
    case 256:
    case 512:
      return true;
    default:
      return false;
  }
}

void dsa_topk_transform_cpu(
    int32_t batch_size, const float* score, const int32_t* lengths,
    int32_t* dst_token_indices, int64_t score_stride, int32_t pool_size,
    int32_t token_topk, int32_t out_cols, const int32_t* page_table,
    int64_t page_table_stride, const int32_t* page_table_row_index,
    const int32_t* topk_indices_offset, const int32_t* row_starts,
