        selected.resize(group_topk);
      }
    }

    const int32_t page_row =
        page_table_row_index == nullptr ? row : page_table_row_index[row];
    VK_EXPECTS(page_table == nullptr || page_row >= 0,
               "page_table_row_index entries must be non-negative");
    const int32_t* page_table_entry =
        page_table == nullptr ? nullptr
                              : page_table + static_cast<size_t>(page_row) *
                                                 page_table_stride;
    const int32_t offset =
        topk_indices_offset == nullptr ? 0 : topk_indices_offset[row];

    const int32_t history_len = valid_groups * pool_size;
    for (int32_t col = 0; col < history_len; ++col) {
      const int32_t group_rank = col / pool_size;
