                         int* bk, int* threads);

/* ------------------------------------------------------------------ */
/* kernels: MLA — absorbed-form Multi-head Latent Attention              */
/* (src/c/vkernels/kernels/mla.hpp, issue #21)                           */
/*                                                                       */
/* q  : [B, H, S_q, kv_lora_rank + qk_rope_head_dim]  fp32              */
