                              q.data(), kv.data(), idx.data(), out.data(),
                              lse.data()),
            VK_OK);
  EXPECT_NEAR(out[0], 4.0f / 1.5f, 1e-6f);
  EXPECT_NEAR(lse[0], 3.0f + std::log2(1.5f), 1e-6f);
}

