  EXPECT_NEAR(out[2], 3.0f, 1e-6f); EXPECT_NEAR(out[3], 4.0f, 1e-6f);
  EXPECT_NEAR(out[4], 0.0f, 1e-6f); EXPECT_NEAR(out[5], 0.0f, 1e-6f);
