    "q [1,S_q,H,dim+tail], kv [1,S_kv,kv_group,dim+tail], "
    "indices [1,S_q,kv_group,topk] int32 (<0/>=S_kv masked) -> "
    "out [1,S_q,H,dim-tail] fp32, optional lse [1,S_q,H] base-2. "
